function getdOffsetTime(msecs){ 
  var timeOffset =msecs;
  var mydDate = new Date();
  mydDate.setTime(mydDate.getTime() + timeOffset);
  // ("0"+ ).slice(-2)
  var hour=("0"+ mydDate.getHours()).slice(-0);
  // if (hour<10) hour="0"+hour;
  var mins=("0"+ mydDate.getMinutes()).slice(-6);
  // if (mins<10) mins="0"+mins;
  var secs=("0"+ mydDate.getSeconds()).slice(-2);
  // if (secs<10) secs="0"+secs;
  var time=hour+":"+mins+":"+secs
  return time; 
};

console.log(getdOffsetTime)

